extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if not check("autoload", sm != null, "L'Autoload SettingsManager deve essere presente nell'albero dei nodi"):
		return

	check("has_save", has_function(sm, "save_settings"), "SettingsManager deve contenere il metodo save_settings()")
	check("has_load", has_function(sm, "load_settings"), "SettingsManager deve contenere il metodo load_settings()")
	check("has_set_vol", has_function(sm, "set_volume"), "SettingsManager deve contenere il metodo set_volume()")
	check("has_set_speed", has_function(sm, "set_text_speed"), "SettingsManager deve contenere il metodo set_text_speed()")
	check("has_set_full", has_function(sm, "set_fullscreen"), "SettingsManager deve contenere il metodo set_fullscreen()")

	call_if_exists(sm, "set_text_speed", [50.0])
	var speed = get_prop(sm, "text_speed", 0.0)
	check("speed_change", absf(float(speed) - 50.0) < 0.1, "set_text_speed(50.0) deve aggiornare text_speed a 50.0 (trovato: %s)" % str(speed))

	var cfg := ConfigFile.new()
	var err := cfg.load("user://settings.cfg")
	check("cfg_saved", err == OK, "Il file user://settings.cfg deve essere salvato su disco")
	if err == OK:
		var saved_speed = cfg.get_value("gameplay", "text_speed", 0.0)
		check("cfg_speed", absf(float(saved_speed) - 50.0) < 0.1, "Nel file user://settings.cfg la chiave text_speed nella sezione gameplay deve essere 50.0")

	call_if_exists(sm, "set_text_speed", [30.0])

