extends Control

@onready var fullscreen_check: CheckButton = %FullscreenCheck
@onready var master_slider: HSlider = %MasterSlider
@onready var music_slider: HSlider = %MusicSlider
@onready var sfx_slider: HSlider = %SfxSlider
@onready var text_speed_slider: HSlider = %TextSpeedSlider
@onready var back_button: Button = %BackButton


func _ready() -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if sm:
		fullscreen_check.button_pressed = bool(sm.get("fullscreen"))
		master_slider.value = float(sm.get("master_volume"))
		music_slider.value = float(sm.get("music_volume"))
		sfx_slider.value = float(sm.get("sfx_volume"))
		text_speed_slider.value = float(sm.get("text_speed"))

	fullscreen_check.toggled.connect(_on_fullscreen_toggled)
	master_slider.value_changed.connect(_on_master_changed)
	music_slider.value_changed.connect(_on_music_changed)
	sfx_slider.value_changed.connect(_on_sfx_changed)
	text_speed_slider.value_changed.connect(_on_text_speed_changed)
	back_button.pressed.connect(_on_back_pressed)


func _on_fullscreen_toggled(toggled_on: bool) -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if sm and sm.has_method("set_fullscreen"):
		sm.set_fullscreen(toggled_on)


func _on_master_changed(value: float) -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if sm and sm.has_method("set_volume"):
		sm.set_volume("Master", value)


func _on_music_changed(value: float) -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if sm and sm.has_method("set_volume"):
		sm.set_volume("Music", value)


func _on_sfx_changed(value: float) -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if sm and sm.has_method("set_volume"):
		sm.set_volume("SFX", value)


func _on_text_speed_changed(value: float) -> void:
	var sm: Node = get_tree().root.get_node_or_null("SettingsManager")
	if sm and sm.has_method("set_text_speed"):
		sm.set_text_speed(value)


func _on_back_pressed() -> void:
	SceneManager.change_scene_to_file("res://ui/title_screen.tscn")

extends Control

const SAVE_FILE_PATH: String = "user://savegame.json"

@onready var continue_button: Button = %ContinueButton
@onready var new_game_button: Button = %NewGameButton
@onready var settings_button: Button = %SettingsButton
@onready var quit_button: Button = %QuitButton


func _ready() -> void:
	var has_save: bool = FileAccess.file_exists(SAVE_FILE_PATH)
	continue_button.visible = has_save

	if has_save:
		continue_button.grab_focus.call_deferred()
	else:
		new_game_button.grab_focus.call_deferred()

	new_game_button.pressed.connect(_on_new_game_pressed)
	continue_button.pressed.connect(_on_continue_pressed)
	settings_button.pressed.connect(_on_settings_pressed)
	quit_button.pressed.connect(_on_quit_pressed)


func _on_new_game_pressed() -> void:
	SceneManager.change_scene_to_file("res://story/story_screen.tscn")


func _on_continue_pressed() -> void:
	SceneManager.change_scene_to_file("res://story/story_screen.tscn")


func _on_settings_pressed() -> void:
	SceneManager.change_scene_to_file("res://ui/settings_menu.tscn")


func _on_quit_pressed() -> void:
	get_tree().quit()

